import 'package:genkit/genkit.dart';
import 'package:genkit_llamadart/genkit_llamadart.dart';

Future<void> main(List<String> args) async {
  final prepared = await llamaDart.prepareModel(
    name: 'local-chat',
    source: ModelSource.parse('hf://unsloth/Qwen3.5-0.8B-GGUF/Qwen3.5-0.8B-Q4_K_M.gguf?revision=6ab461498e2023f6e3c1baea90a8f0fe38ab64d0'),
    modelParams: const ModelParams(contextSize: 4096, device: ComputeDevice.cpu),
  );
  final ai = prepared.createGenkit();
  try {
    final response = await ai.generate(prompt: 'Say hello in one sentence.');
    print(response.text);
  } finally {
    await prepared.dispose();
    await ai.shutdown();
  }
}
